-- Gjaldið per gat felur í sér bæði vinnu og efni. notes = lýsingin sem fer á reikninginn.
on conflict (scope, category, size_min_mm, size_max_mm, effective_from) do update set rate_an_vsk = excluded.rate_an_vsk, notes = excluded.notes, size_label = excluded.size_label, updated_at = now();
